package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

// Task представляет единицу работы, которую нужно выполнить.
type Task struct {
	ID   int
	Data string
}

// Result — результат выполнения задачи.
type Result struct {
	TaskID int
	Output string
	Err    error
}

// PoolWorker — пул воркеров с ограничением параллелизма.
// Он принимает задачи из канала и обрабатывает их в фиксированном количестве горутины-воркеров.
type PoolWorker struct {
	taskCh     chan Task
	resultCh   chan Result
	wg         sync.WaitGroup
	numWorkers int
	ctx        context.Context
	cancel     context.CancelFunc
}

// NewPoolWorker создаёт новый пул воркеров.
//
// Параметры:
//   - numWorkers: количество параллельных воркеров (должно быть > 0).
//   - bufferSize: размер буфера для каналов задач и результатов.
//     Если <= 0, используется небуферизованный канал.
//
// Возвращает указатель на инициализированный PoolWorker.
func NewPoolWorker(numWorkers, bufferSize int) *PoolWorker {
	if numWorkers <= 0 {
		numWorkers = 1 // Защита от некорректного значения
	}

	var taskCh chan Task
	var resultCh chan Result

	if bufferSize > 0 {
		taskCh = make(chan Task, bufferSize)
		resultCh = make(chan Result, bufferSize)
	} else {
		taskCh = make(chan Task)
		resultCh = make(chan Result)
	}

	ctx, cancel := context.WithCancel(context.Background())

	return &PoolWorker{
		taskCh:     taskCh,
		resultCh:   resultCh,
		numWorkers: numWorkers,
		ctx:        ctx,
		cancel:     cancel,
	}
}

// Start запускает все воркеры пула.
// Каждый воркер начинает читать задачи из taskCh и отправлять результаты в resultCh.
// Метод идемпотентен: повторный вызов не создаст дополнительные воркеры.
func (p *PoolWorker) Start() {
	for i := 0; i < p.numWorkers; i++ {
		p.wg.Add(1)
		go p.worker(i)
	}
}

// worker — внутренняя функция, выполняющая цикл обработки задач одним воркером.
// Воркер читает задачи из taskCh до тех пор, пока канал не будет закрыт или контекст не будет отменён.
func (p *PoolWorker) worker(id int) {
	defer p.wg.Done()

	for {
		select {
		case <-p.ctx.Done():
			// Контекст отменён — выходим из цикла
			return

		case task, ok := <-p.taskCh:
