/// <returns>Последовательность элементов, у которых все значения ключей различны (первое вхождение сохраняется).</returns>
public static IEnumerable<T> Distinct<T, K>(this IEnumerable<T> src, Func<T, K> key)
{
    // Множество для хранения уже встреченных ключей.
    // HashSet обеспечивает быструю проверку наличия и добавление элементов (O(1) в среднем).
    var seen = new HashSet<K>();

    // Перебираем каждый элемент исходной коллекции
    foreach (var x in src)
    {
        // Вычисляем ключ для текущего элемента с помощью переданной функции key.
        // Метод Add возвращает true, если ключ был успешно добавлен (т.е. ранее не встречался),
        // и false, если такой ключ уже присутствует в множестве.
        if (seen.Add(key(x)))
        {
            // Если ключ новый (Add вернул true), возвращаем текущий элемент в результат.
            // Это гарантирует, что в итоговой последовательности будет только первое вхождение
            // каждого уникального ключа.
            yield return x;
        }
    }
}
