/**
 * Создаёт функцию-обёртку, которая откладывает вызов исходной функции
 * до тех пор, пока не пройдёт заданное время без повторных вызовов.
 *
 * @param fn - Исходная функция, которую нужно «задебаунсить».
 * @param ms - Задержка в миллисекундах перед выполнением функции.
 * @returns Обёрнутая функция с той же сигнатурой аргументов, что и `fn`.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера.
  // Изначально она не определена (undefined), так как таймер ещё не создан.
  let timer: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, принимающую те же аргументы, что и исходная `fn`.
  return (...args: Parameters<T>) => {
    // Если таймер уже существует (предыдущий вызов ещё не завершился),
    // очищаем его — это отменяет предыдущее запланированное выполнение.
    if (timer) clearTimeout(timer);

    // Устанавливаем новый таймер на задержку `ms` миллисекунд.
    // По истечении времени будет вызвана исходная функция `fn`
    // с последними переданными аргументами `args`.
    timer = setTimeout(() => fn(...args), ms);
  };
}
```

