/**
 * Универсальная функция для повторного выполнения блока кода при возникновении IOException.
 *
 * @param times Количество попыток выполнения блока (включая первую).
 * @param block Лямбда-функция, содержащая код, который нужно выполнить.
 * @return Результат выполнения блока, если он завершился успешно.
 * @throws IOException Если все попытки завершились исключением IOException.
 * @throws IllegalStateException Если передано количество попыток <= 0.
 */
fun <T> retry(times: Int, block: () -> T): T {
    // Переменная для хранения последнего возникшего исключения (IOException)
    var last: Throwable? = null

    // Цикл, выполняющий блок `times` раз
    repeat(times) {
        try {
            // Пытаемся выполнить блок кода и сразу вернуть его результат,
            // если исключение не произошло
            return block()
        } catch (e: IOException) {
            // Если произошло IOException, сохраняем его в переменную `last`,
            // чтобы продолжить следующую попытку
            last = e
        }
    }

    // Если цикл завершился без успешного возврата (все попытки упали с IOException),
    // бросаем последнее сохраненное исключение.
    // Если `last` равно null (что возможно только при times <= 0),
    // бросаем IllegalStateException с пояснением
    throw last ?: IllegalStateException("times must be > 0")
}
```

